          .parallel(i)
          .vectorize(j, vec);

    init_B.compute_root()
          .parallel(i)
          .vectorize(j, vec);

    init_C.compute_root()
          .parallel(i)
          .vectorize(j, vec);

    init_A.realize(A);
    init_B.realize(B);
    init_C.realize(C);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;
    int m = M;

    // Scalars
    num_t alpha;
    num_t beta;

    // Buffers
    // Original arrays:
    //   C[n][n], A[n][m], B[n][m]
    // We map:
    //   C[i][j]   -> C(j, i) with shape (n, n)
    //   A[i][j]   -> A(j, i) with shape (m, n)
    //   B[i][j]   -> B(j, i) with shape (m, n)
    Buffer<num_t, 2> C(n, n);
    Buffer<num_t, 2> A(m, n);
    Buffer<num_t, 2> B(m, n);

    // ImageParams to feed buffers into Halide pipeline
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");

    // Initialize data
    init_array(n, m, &alpha, &beta, C, A, B);

    // Bind buffers to ImageParams
    C_param.set(C);
    A_param.set(A);
    B_param.set(B);

    // Vars and reduction domains
    Var i("i"), j("j");

    // Halide implementation of kernel_syr2k:
    //
    // Original C kernel:
    //
    // for (i = 0; i < _PB_N; i++) {
    //   for (j = 0; j <= i; j++)
    //     C[i][j] *= beta;
    //   for (k = 0; k < _PB_M; k++)
    //     for (j = 0; j <= i; j++) {
    //       C[i][j] += A[j][k]*alpha*B[i][k] + B[j][k]*alpha*A[i][k];
    //     }
    // }
    //
    // Index mapping into Buffers:
    //   C[i][j]   -> C_param(j, i)
    //   A[j][k]   -> A_param(k, j)
    //   B[i][k]   -> B_param(k, i)
    //   B[j][k]   -> B_param(k, j)
    //   A[i][k]   -> A_param(k, i)
    //
    // We implement this as:
    //   1) Copy C into a working Func syr2k(j, i).
    //   2) Scale the lower-triangular part (j <= i) by beta.
    //   3) For all i, j, k with j <= i, accumulate the rank-2k update.
    //
    // Steps (2) and (3) use RDom predicates (RDom::where) so that we
    // *skip* the heavy arithmetic for j > i instead of using select(),
    // which would evaluate both branches and waste work.

    Func syr2k("syr2k");

    Expr alpha_e = Expr(alpha);
    Expr beta_e  = Expr(beta);

    // Step 1: Start from the original C.
    syr2k(j, i) = C_param(j, i);

    // Step 2: scale lower-triangular part by beta: C[i][j] *= beta for j <= i.
    // RDom over full n x n box, then we predicate to restrict to j <= i.
    RDom r_beta(0, n, 0, n, "r_beta");  // r_beta.x -> j, r_beta.y -> i
    r_beta.where(r_beta.x <= r_beta.y);
    syr2k(r_beta.x, r_beta.y) *= beta_e;

    // Step 3: symmetric rank-2k update on lower triangle.
    //
    // We use a 3D reduction domain:
    //   r.x = k in [0, m)
    //   r.y = i in [0, n)
    //   r.z = j in [0, n)
    // and restrict to j <= i via r.where.
    //
    // For every (i, j, k) with j <= i:
    //   syr2k(j, i) += alpha * (A[j][k]*B[i][k] + B[j][k]*A[i][k]);
    //
    // Mapping to ImageParams:
    //   A[j][k] -> A_param(k, j)  == A_param(r.x, r.z)
    //   B[i][k] -> B_param(k, i)  == B_param(r.x, r.y)
    //   B[j][k] -> B_param(k, j)  == B_param(r.x, r.z)
    //   A[i][k] -> A_param(k, i)  == A_param(r.x, r.y)
    RDom r(0, m, 0, n, 0, n, "r");  // (k, i, j)
    r.where(r.z <= r.y);            // j <= i

    Expr Ajk = A_param(r.x, r.z);
    Expr Bik = B_param(r.x, r.y);
    Expr Bjk = B_param(r.x, r.z);
    Expr Aik = A_param(r.x, r.y);

    syr2k(r.z, r.y) += alpha_e * (Ajk * Bik + Bjk * Aik);

    // ------------------------
    // Schedule
    // ------------------------

    Target target = get_host_target();
    const int vec = natural_vector_size(type_of<num_t>(), target);

    // Pure definition: copy C -> syr2k.
    // j is the fastest-varying coordinate (stride-1), so we vectorize over j
    // and parallelize over i (rows).
    syr2k
        .reorder(j, i)     // j inner, i outer (row-major access in Buffer)
        .compute_root()
        .parallel(i)
        .vectorize(j, vec);

    // First update (index 0): scaling by beta on lower triangle.
    // RVars for readability.
    RVar rb_x = r_beta.x;  // column j
    RVar rb_y = r_beta.y;  // row i

    syr2k.update(0)
        // Make j (rb_x) the innermost loop for contiguous access to syr2k(j,i)
        .reorder(rb_x, rb_y)
        // Parallelize across rows; each row is independent in this update.
        .parallel(rb_y)
        // Vectorize across columns within a row.
        .vectorize(rb_x, vec);

    // Second update (index 1): rank-2k accumulation on lower triangle.
    RVar r_k = r.x;  // k in [0, m)
    RVar r_i = r.y;  // i in [0, n)
    RVar r_j = r.z;  // j in [0, n)

    syr2k.update(1)
        // Innermost: j (columns of C, stride-1); then k; outermost: i (rows).
        // The predicate r_j <= r_i is preserved.
        .reorder(r_j, r_k, r_i)
        // Parallelize across rows i; each row is independent.
        .parallel(r_i)
        // Vectorize across columns j for good write locality into syr2k(j,i).
        .vectorize(r_j, vec);

    // JIT-compile the kernel for the chosen target
    syr2k.compile_jit(target);

    // Time the execution
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write result back into C
    syr2k.realize(C);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result (mainly to prevent dead-code elimination
    // and to allow correctness checking if desired).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < n; ii++) {
            for (int jj = 0; jj < n; jj++) {
                // Recall: C(ii,jj) in C maps to C(jj,ii) in Buffer
                std::cerr << C(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
