    // Problem size
    int n = N;
    int m = M;

    // Scalars
    num_t alpha;
    num_t beta;

    // Buffers
    // Original arrays:
    //   C[n][n], A[n][m], B[n][m]
    // We map C[i][j] -> C(j, i) with shape (n, n)
    // A[i][j] (n x m) -> A(j, i) with shape (m, n)
    // B[i][j] (n x m) -> B(j, i) with shape (m, n)
