    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");

    // Initialize data
    init_array(n, m, &alpha, &beta, C, A, B);

    // Bind buffers to ImageParams
    C_param.set(C);
    A_param.set(A);
    B_param.set(B);

    // Vars
    Var j("j"), i("i");

    // ---------------------------------------------
    // Optimized Halide implementation of kernel_syr2k
    // ---------------------------------------------
    //
    // Original C kernel:
    //
    // for (i = 0; i < _PB_N; i++) {
    //   for (j = 0; j <= i; j++)
    //     C[i][j] *= beta;
    //   for (k = 0; k < _PB_M; k++)
    //     for (j = 0; j <= i; j++) {
    //       C[i][j] += A[j][k]*alpha*B[i][k] + B[j][k]*alpha*A[i][k];
    //     }
    // }
    //
    // That is:
    //   For j <= i:
    //     C[i][j] = beta * C[i][j] +
    //               alpha * sum_k ( A[j][k]*B[i][k] + B[j][k]*A[i][k] )
    //   For j  > i:
    //     C[i][j] unchanged.
    //
    // In terms of our buffer mapping:
    //
    //   C[i][j]   -> C_param(j, i)
    //   A[j][k]   -> A_param(k, j)
    //   B[i][k]   -> B_param(k, i)
    //   B[j][k]   -> B_param(k, j)
    //   A[i][k]   -> A_param(k, i)
    //
    // We express the entire computation as a single pure Func with an
    // embedded reduction over k (using Halide::sum). This eliminates
    // explicit update definitions and gives us cleaner scheduling
    // freedom while preserving the mathematical result (up to normal
    // FP roundoff).

    Func syr2k("syr2k");

    // Promote scalar alpha, beta to Exprs once so they become constants
    // in the generated code.
    Expr alpha_e = Expr(alpha);
    Expr beta_e  = Expr(beta);

    // Reduction domain over k (0..m-1).
    RDom rk(0, m, "rk");

    // Per (i, j) contribution from the rank-2k update:
    //
    //   sum_k alpha * ( A[j][k]*B[i][k] + B[j][k]*A[i][k] )
    //
    // With our buffer mapping:
    //   A[j][k] -> A_param(rk, j)
    //   B[i][k] -> B_param(rk, i)
    //   B[j][k] -> B_param(rk, j)
    //   A[i][k] -> A_param(rk, i)
    //
    // We deliberately make 'k' the innermost loop (via this reduction),
    // so that we stream contiguous elements A_param(rk, *) and B_param(rk, *)
    // across their first dimension. This is significantly more cache-
    // friendly than repeatedly scanning along the second dimension.
    Expr rank2k_update =
        sum(alpha_e * (A_param(rk, j) * B_param(rk, i) +
                       B_param(rk, j) * A_param(rk, i)));

    // Original C value of C[i][j].
    Expr c_old = C_param(j, i);

    // Final result:
    //   - For j <= i: triangular part updated as in C kernel.
    //   - For j  > i: value is left unchanged.
    syr2k(j, i) = select(j <= i,
                         beta_e * c_old + rank2k_update,
                         c_old);

    // --------------------
    // Schedule for syr2k
    // --------------------
    //
    // Goals:
    //   * Good data locality:
    //       - For each (i, j), reduction over k streams contiguous
    //         rows of A and B across their first dimension.
    //   * Reasonable cache tiling over (i, j).
    //   * Exploit SIMD on x86 via vectorization in j.
    //   * Parallelize outer tiles across CPU cores.
    //
    // The reduction over k is kept innermost (Halide's default for
    // reductions inside a pure definition), so A_param(rk, *) and
    // B_param(rk, *) are accessed with unit stride.

    Var jo("jo"), io("io"), ji("ji"), ii("ii");

    // Choose a vector width based on the element type:
    //   - 8 lanes for 32-bit (float)
    //   - 4 lanes for 64-bit (double)
    const int vec_width = (sizeof(num_t) == 4) ? 8 : 4;

    // Tile the (j, i) space into 64x32 tiles.
    // Layout of loops (from outermost to innermost) will be roughly:
    //   io, jo, ii, ji, rk
    // So for each tile of C, we compute all (i, j) inside the tile,
    // and for each such element we run the inner reduction over k.
    // Within a tile, ji is vectorized.
    syr2k
        .tile(j, i, jo, io, ji, ii, 64, 32)
        .vectorize(ji, vec_width)
        .parallel(io);  // parallelize across bands of rows

    // JIT-compile the kernel with a target that matches the host.
    Target target = get_jit_target_from_environment();
    syr2k.compile_jit(target);

    // --------------------
    // Execute and time it
    // --------------------
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write result back into C
    syr2k.realize(C);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result (mainly to prevent dead-code elimination
    // and to allow correctness checking if desired).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < n; ii++) {
            for (int jj = 0; jj < n; jj++) {
                // Recall: C(ii,jj) in C maps to C(jj,ii) in Buffer
                std::cerr << C(jj, ii) << '\n';
            }
        }
    }

