    // Promote scalars into Halide Exprs of the correct type.
    Expr alpha_e = cast<num_t>(Expr(alpha));
    Expr beta_e  = cast<num_t>(Expr(beta));

    // Base value of C(i,j)
    Expr C_ij = C_param(j, i);

    // Initial multiplication by beta for j <= i; otherwise keep original C.
    // This matches:
    //   if (j <= i) C[i][j] *= beta; else C[i][j] unchanged.
    syr2k(j, i) = select(j <= i,
                         beta_e * C_ij,
                         C_ij);

    // Rank-2k update, only for j <= i.
    // We factor common subexpressions to reduce redundant loads and FLOPs.
    Expr A_jk = A_param(k, j);  // A[j][k]
    Expr B_ik = B_param(k, i);  // B[i][k]
    Expr B_jk = B_param(k, j);  // B[j][k]
    Expr A_ik = A_param(k, i);  // A[i][k]

    Expr update_term = alpha_e * (A_jk * B_ik + B_jk * A_ik);

    syr2k(j, i) += select(j <= i,
                          update_term,
                          cast<num_t>(0));

    // --------------------------------------------------------------------
    // Schedule
    // --------------------------------------------------------------------
    //
    // Goals:
    //   * Preserve the original loop semantics.
    //   * Keep k (the reduction dimension) innermost to stream through A,B.
    //   * Make j the innermost spatial dimension to write C contiguously.
    //   * Parallelize across blocks of rows in i.
    //   * Vectorize across j to exploit SIMD.
    //
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Split i into outer (io) and inner (ii) to get reasonably large
    // chunks for parallel work, while keeping inner loops cache-friendly.
    Var io("io"), ii("ii");

    // Pure definition: io outer, ii middle, j innermost. This gives:
    // for (io)
    //   for (ii)
    //     for (j)  // vectorized
    //       ...
    syr2k
        .split(i, io, ii, 64)
        .reorder(j, ii, io)
        .parallel(io)         // parallelize across blocks of rows
        .vectorize(j, vec_width); // vectorize contiguous j dimension

    // Update definition (the reduction):
    //
    // Desired loop nest:
    //   for (io)
    //     for (ii)
    //       for (k)
    //         for (j)  // vectorized
    //           syr2k(i,j) += ...
    //
    // reorder() arguments are specified from innermost outwards, so
    // reorder(j, k, ii, io) yields loops: io (outer) -> ii -> k -> j (inner).
    syr2k.update()
        .reorder(j, k, ii, io)
        .parallel(io)
        .vectorize(j, vec_width);

    // JIT-compile the kernel for the chosen target.
    syr2k.compile_jit(target);

    // Time the execution
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write result back into C
    syr2k.realize(C);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result (mainly to prevent dead-code elimination
    // and to allow correctness checking if desired).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < n; ii++) {
            for (int jj = 0; jj < n; jj++) {
                // Recall: C(ii,jj) in C maps to C(jj,ii) in Buffer
                std::cerr << C(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
